const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define region: Northern Madagascar, latitude -12 to -15
  const region = ee.Geometry.Rectangle([43, -15, 50, -12]);

  // 2. Load CHIRPS precipitation data
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

  // 3. Calculate precipitation for Dec 2018 - Jan 2019
  const target = chirps
    .filterDate('2018-12-01', '2019-02-01')
    .filterBounds(region);

  const targetSize = target.size().getInfo();
  console.log(`Target period (Dec2018-Jan2019) images: ${targetSize}`);

  if (targetSize === 0) {
    console.log("No data for target period.");
    console.log("C1");
    return;
  }

  const targetRain = target.sum().reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Target rain (Dec2018-Jan2019): ${targetRain?.toFixed(2) || 'null'} mm`);

  // 4. Calculate long-term average for Dec-Jan (2000-2019)
  let climatologyRain = 0;
  let validYears = 0;

  for (let year = 2000; year <= 2018; year++) {
    const yearData = chirps
      .filterDate(`${year}-12-01`, `${year + 1}-02-01`)
      .filterBounds(region);

    if (yearData.size().getInfo() > 0) {
      const yearRain = yearData.sum().reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: region,
        scale: 5000,
        maxPixels: 1e9
      }).get('precipitation').getInfo();

      if (yearRain !== null && !isNaN(yearRain)) {
        climatologyRain += yearRain;
        validYears++;
      }
    }
  }

  if (validYears === 0) {
    console.log("No valid climatology data.");
    console.log("C1");
    return;
  }

  climatologyRain = climatologyRain / validYears;
  console.log(`Climatology (${validYears} years): ${climatologyRain.toFixed(2)} mm`);

  // 5. Validation and answer
  if (targetRain === null || isNaN(targetRain)) {
    console.log("Target calculation failed.");
    console.log("C3");
    return;
  }

  const difference = targetRain - climatologyRain;
  console.log(`Difference: ${difference.toFixed(2)} mm`);

  if (targetRain < climatologyRain) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
